// @name Gallery
// @background #000000
// @refresh 3600
// Photos from the FrameOS Gallery (gallery.frameos.net), full screen: swipe
// left (or tap the right half) for the next one, swipe right (or tap the left
// half) for the one before, and a category at the bottom for another gallery.
// A swipe in from the screen's edge is the frame's scene switch, not this.
//
// The photo on screen is kept (fetchImage's `keep`), decoded once at the
// panel's size: a tap that only changes the caption, a hover or the scene's
// interval draws it again without a download. The gallery hands out a random
// photo per request, so "back" is the one photo kept before this one; past
// it there is nothing to go back to. Each kept photo is the interpreter's: an
// ESP32 short of memory lets the interpreter go and the photos with it, and
// the next render fetches again.
let W = 480, H = 480 // the photo in pixels, set by each render
const KEPT = 2 // the photo on screen and the one before it
const CATEGORIES = [
  ['cute', 'Cute'],
  ['space-gallery', 'Space'],
  ['masterpieces', 'Buildings'],
  ['low-poly-animals', 'Low poly'],
]

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it. The photo stays as it is:
// only the labels and buttons over it change.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-black text-white',
    tag: 'px-3 py-1 bg-black/60',
    error: 'p-3 bg-red-900/80',
    chip: 'bg-black/60 text-white active:bg-white/30',
    chipOn: 'bg-white text-black',
    half: 'border-white',
  },
  high: {
    page: 'bg-white text-black',
    tag: 'px-[10px] py-[2px] bg-white text-black border-2 border-black',
    error: 'p-[10px] bg-white text-black border-2 border-black',
    chip: 'bg-white text-black border-2 border-black',
    chipOn: 'bg-black text-white border-2 border-black',
    half: 'border-black',
  },
}

// What lasts the interpreter: the kept photos, newest last, and where we are.
let shown = [] // [{ ref, category, n }]
let at = -1    // index into shown
let want = 0   // +1: a new photo on the next render
let failed = ''

// What lasts the scene: the category and how many photos it has fetched.
let S = null
const load = () => {
  if (S === null) S = Object.assign({ category: 'cute', count: 0 }, frameos.recall('gallery') ?? {})
}
const save = () => frameos.remember('gallery', S)

// Where a photo the panel's size does not fit beside the frame's own picture
// (the reTerminal E1004: 1200x1600 is 3.84 MB, more than its memory has in one
// block), the kept photos go first, then the gallery is asked for a smaller
// one, which the <img> stretches to the panel: 2 halves each side, 4 quarters.
let shrink = 1
const noRoom = (photo) => !photo.image && /no room/i.test(String(photo.error ?? ''))

const fetchNext = () => {
  let photo = null
  for (;;) {
    const w = Math.max(1, Math.round(W / shrink)), h = Math.max(1, Math.round(H / shrink))
    const url = `https://gallery.frameos.net/image?category=${encodeURIComponent(S.category)}` +
      `&width=${w}&height=${h}&fit=cover&format=jpg`
    photo = frameos.fetchImage(url, { keep: true, width: w, height: h })
    if (!noRoom(photo)) break
    if (shown.length > 0) {
      for (const kept of shown) frameos.releaseImage(kept.ref)
      shown = []
      at = -1
    } else if (shrink < 4) {
      shrink *= 2
    } else {
      break
    }
  }
  if (!photo.image) {
    failed = photo.error ?? 'the gallery sent nothing'
    return
  }
  failed = ''
  S.count += 1
  save()
  // Past the end of what is kept: the oldest goes.
  shown = shown.slice(0, at + 1)
  shown.push({ ref: photo.image, category: S.category, n: S.count })
  while (shown.length > KEPT) frameos.releaseImage(shown.shift().ref)
  at = shown.length - 1
}

// +1 the next photo (a new one, or the one we came back from), -1 the one before.
const go = (step) => {
  if (step < 0 && at > 0) at -= 1
  else if (step > 0 && at < shown.length - 1) at += 1
  else if (step > 0) want = 1
}

const pick = (category) => {
  if (category === S.category) return
  S.category = category
  save()
  want = 1
}

// On a round panel the photo fills the circle, the caption sits in the arc
// at the top and the categories in two rows in the arc at the bottom, each
// as wide as the circle is there.
const getRound = (context, t, photo, label) => {
  const uiW = context.imageWidth, uiH = context.imageHeight
  const size = Math.min(uiW, uiH), r = size / 2
  const k = r / 240
  const n = (v) => Math.max(1, Math.round(v * k))
  const text = Math.max(14, n(14))
  const inset = Math.max(12, n(12))
  const chord = (y) => 2 * Math.sqrt(Math.max(0, (r - inset) ** 2 - y * y))
  const rowH = n(40)
  const row = (cy, items) => {
    const w = Math.round(chord(cy + rowH / 2) - n(8))
    return (
      <div className={`absolute left-[${Math.round((uiW - w) / 2)}px] top-[${Math.round(uiH / 2 + cy - rowH / 2)}px] w-[${w}px] h-[${rowH}px] flex gap-2`}>
        {items.map(([id, name]) => (
          <div className={`flex-1 flex items-center justify-center rounded-full ${id === S.category ? t.chipOn : t.chip}`}
            onClick={() => pick(id)}>
            <span className={`text-[${text}px] font-semibold`}>{name}</span>
          </div>
        ))}
      </div>
    )
  }
  const caption = `${label} · ${photo ? `Photo ${photo.n}${at < shown.length - 1 ? ' (back)' : ''}` : 'No photo'}`
  const errorW = Math.round(r * 1.5)
  // The halves that turn the photos, between the caption and the categories.
  const zoneTop = Math.round(uiH / 2 - r * 0.8 + n(22))
  const zoneH = Math.round(uiH / 2 + r * 0.5 - rowH / 2 - n(8)) - zoneTop
  return (
    <div className={`w-full h-full ${t.page}`}
      onSwipe={(e) => go(e.direction === 'left' ? 1 : e.direction === 'right' ? -1 : 0)}>
      {photo ? <img className="absolute inset-0 w-full h-full object-cover" src={photo.ref} /> : null}
      {halves(t, uiW, zoneTop, zoneH)}
      <div className={`absolute left-0 w-[${uiW}px] top-[${Math.round(uiH / 2 - r * 0.8 - n(14))}px] h-[${n(28)}px] flex items-center justify-center`}>
        <span className={`rounded-full text-[${text}px] font-semibold ${t.tag}`}>{caption}</span>
      </div>
      {failed ? (
        <div className={`absolute left-[${Math.round((uiW - errorW) / 2)}px] w-[${errorW}px] top-[${Math.round(uiH / 2 - r * 0.32)}px] rounded-xl ${t.error}`}>
          <span className={`text-[${text}px]`}>{`Could not load a photo: ${failed}`}</span>
        </div>
      ) : null}
      {row(r * 0.5, CATEGORIES.slice(0, 2))}
      {row(r * 0.5 + rowH + n(8), CATEGORIES.slice(2))}
    </div>
  )
}

// The two halves of the photo that turn it, between the labels at the top and
// the categories: left for the one before, right for the next. The keys on
// one light its outer edge (its own focus look, not the ring, which drew a
// line down the middle of the photo).
const halves = (t, uiW, top, height) => {
  const w = Math.round(uiW / 2)
  return [
    <div className={`absolute left-0 top-[${top}px] w-[${w}px] h-[${height}px] ${t.half} focus:border-l-8`} onClick={() => go(-1)} />,
    <div className={`absolute right-0 top-[${top}px] w-[${uiW - w}px] h-[${height}px] ${t.half} focus:border-r-8`} onClick={() => go(1)} />,
  ]
}

export function get(app, context) {
  load()
  const t = highContrast(app) ? THEMES.high : THEMES.color
  // Fetched at the panel's own pixels; the tap halves follow the UI's width.
  const uiW = context?.imageWidth ?? app.frame.width
  const scale = app.frame.scale ?? 1
  W = Math.round(uiW * scale)
  H = Math.round((context?.imageHeight ?? app.frame.height) * scale)
  if (want > 0 || shown.length === 0) {
    want = 0
    fetchNext()
  }
  const photo = shown[at]
  const label = CATEGORIES.find(([id]) => id === (photo?.category ?? S.category))?.[1] ?? S.category
  if (context?.round === true) return getRound(context, t, photo, label)
  const uiH = context?.imageHeight ?? app.frame.height
  // The categories in one row where each name fits its chip on one line,
  // else in two (a watch).
  const chipW = (uiW - 24 - 3 * 8) / 4
  const longest = CATEGORIES.reduce((a, [, name]) => (name.length > a.length ? name : a), '')
  const oneRow = frameos.measureText([longest], { className: 'text-sm font-semibold', width: Math.floor(chipW) - 8 })[0] <= 24
  const rows = oneRow ? [CATEGORIES] : [CATEGORIES.slice(0, 2), CATEGORIES.slice(2)]
  const chipsH = rows.length * 40 + (rows.length - 1) * 8
  return (
    <div className={`w-full h-full ${t.page}`}
      onSwipe={(e) => go(e.direction === 'left' ? 1 : e.direction === 'right' ? -1 : 0)}>
      {photo ? <img className="absolute inset-0 w-full h-full object-cover" src={photo.ref} /> : null}
      {halves(t, uiW, 48, uiH - 48 - 12 - chipsH - 8)}
      <div className="absolute top-3 left-3 right-3 flex items-center justify-between">
        <span className={`rounded-full text-sm font-semibold ${t.tag}`}>{label}</span>
        <span className={`rounded-full text-sm ${t.tag}`}>
          {photo ? `Photo ${photo.n}${at < shown.length - 1 ? ' (back)' : ''}` : 'No photo'}
        </span>
      </div>
      {failed ? (
        <div className={`absolute inset-x-6 top-[200px] rounded-xl ${t.error}`}>
          <span className="text-sm">{`Could not load a photo: ${failed}`}</span>
        </div>
      ) : null}
      <div className="absolute bottom-3 left-3 right-3 flex flex-col gap-2">
        {rows.map((row) => (
          <div className="flex gap-2">
            {row.map(([id, name]) => (
              <div className={`flex-1 flex items-center justify-center h-10 rounded-full ${id === S.category ? t.chipOn : t.chip}`}
                onClick={() => pick(id)}>
                <span className="text-sm font-semibold whitespace-nowrap">{name}</span>
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  )
}
